        for i in seq(0, m):
            Q[i, k] = A[i, k] / R[k, k]

        # For each j > k, update R[k, j] and A[:, j]
        for j in seq(k + 1, n):
            # R[k, j] = Q[:, k]^T * A[:, j]
            R[k, j] = 0.0
            for i in seq(0, m):
                R[k, j] += Q[i, k] * A[i, j]

            # A[:, j] = A[:, j] - Q[:, k] * R[k, j]
            for i in seq(0, m):
                A[i, j] = A[i, j] - Q[i, k] * R[k, j]


