#    j is inner. This gives innermost iteration over j (contiguous in
#    memory) and allows Q[i, k] to be reused across many j.
#
# Before:
#   for j in seq(k + 1, n):
#       for i in seq(0, m):
#           R[k, j] += Q[i, k] * A[i, j]
#
# After:
#   for i in seq(0, m):
